@using sv_bf8fe757cfd1438abdf655162a530dbf.Services
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

@if (_loading)
{
    <div class="catalog-loading">
        <p><em>Loading products...</em></p>
    </div>
}
else if (_error is not null)
{
    <div class="catalog-error alert alert-danger">
        <p>Error loading products: @_error</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
    </div>
}
else
{
    <div class="catalog-container">
        <aside class="catalog-sidebar">
            <h4>Filters</h4>

            <div class="filter-section">
                <h5>Categories</h5>
                @if (_categories is not null)
                {
                    @foreach (var category in _categories)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="checkbox" id="cat-@category"
                                   checked="@(_selectedCategories.Contains(category))"
                                   @onchange="e => ToggleCategory(category, (bool?)e.Value ?? false)" />
                            <label class="form-check-label" for="cat-@category">@category</label>
                        </div>
                    }
                }
            </div>

            <div class="filter-section">
                <h5>Price Range</h5>
                <div class="mb-2">
                    <label for="min-price">Min Price</label>
                    <input id="min-price" type="number" class="form-control" placeholder="Min"
                           @bind="_minPrice" />
                </div>
                <div class="mb-2">
                    <label for="max-price">Max Price</label>
                    <input id="max-price" type="number" class="form-control" placeholder="Max"
                           @bind="_maxPrice" />
                </div>
            </div>

            <div class="filter-section">
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="in-stock-only"
                           @bind="_inStockOnly" />
                    <label class="form-check-label" for="in-stock-only">In Stock Only</label>
                </div>
            </div>

            <div class="filter-actions">
                <button class="btn btn-primary w-100 mb-2" @onclick="ApplyFiltersAsync">Apply Filters</button>
                <button class="btn btn-secondary w-100" @onclick="ClearFiltersAsync">Clear Filters</button>
            </div>
        </aside>

        <main class="catalog-main">
            <div class="catalog-toolbar">
                <div class="toolbar-sort">
                    <label for="sort-select">Sort by:</label>
                    <select id="sort-select" class="form-select" @onchange="OnSortChangedAsync">
                        <option value="price_asc" selected="@(_sortBy == "price_asc")">Price: Low to High</option>
                        <option value="price_desc" selected="@(_sortBy == "price_desc")">Price: High to Low</option>
                        <option value="name_asc" selected="@(_sortBy == "name_asc")">Name: A-Z</option>
                        <option value="rating_desc" selected="@(_sortBy == "rating_desc")">Rating: Highest</option>
                    </select>
                </div>
                <div class="toolbar-info">
                    @if (_result is not null && _result.TotalCount > 0)
                    {
                        var start = (_result.Page - 1) * _result.PageSize + 1;
                        var end = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
                        <span>Showing @start–@end of @_result.TotalCount products</span>
                    }
                </div>
            </div>

            @if (_result is null || _result.Items.Count == 0)
            {
                <div class="catalog-empty">
                    <p>No products found. Try adjusting your filters.</p>
                </div>
            }
            else
            {
                <div class="product-grid">
                    @foreach (var product in _result.Items)
                    {
                        <ProductCard Product="product"
                                     OnProductSelected="OnProductSelected"
                                     OnAddToCart="OnAddToCart" />
                    }
                </div>

                <nav class="catalog-pagination" aria-label="Product pagination">
                    <ul class="pagination justify-content-center">
                        <li class="page-item @(_currentPage <= 1 ? "disabled" : "")">
                            <button class="page-link" disabled="@(_currentPage <= 1)"
                                    @onclick="() => GoToPageAsync(_currentPage - 1)">Previous</button>
                        </li>
                        @for (var i = 1; i <= _totalPages; i++)
                        {
                            var pageNum = i;
                            <li class="page-item @(pageNum == _currentPage ? "active" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(pageNum)">@pageNum</button>
                            </li>
                        }
                        <li class="page-item @(_currentPage >= _totalPages ? "disabled" : "")">
                            <button class="page-link" disabled="@(_currentPage >= _totalPages)"
                                    @onclick="() => GoToPageAsync(_currentPage + 1)">Next</button>
                        </li>
                    </ul>
                </nav>
            }
        </main>
    </div>
}

@code {
    private const int PageSize = 12;

    private bool _loading = true;
    private string? _error;

    private List<string>? _categories;
    private HashSet<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private int _totalPages = 1;
    private PagedResult<Product>? _result;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        try
        {
            _loading = true;
            _error = null;

            var categoriesTask = ProductService.GetCategoriesAsync();
            var searchTask = SearchProductsAsync();

            _categories = await categoriesTask;
            await searchTask;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SearchProductsAsync()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );

        _result = await ProductService.SearchAsync(filter, _sortBy, _currentPage, PageSize);
        _totalPages = Math.Max(1, (int)Math.Ceiling((double)_result.TotalCount / PageSize));
    }

    private async Task ApplyFiltersAsync()
    {
        _currentPage = 1;
        await RefreshProductsAsync();
    }

    private async Task ClearFiltersAsync()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        _currentPage = 1;
        await RefreshProductsAsync();
    }

    private async Task OnSortChangedAsync(ChangeEventArgs e)
    {
        _sortBy = e.Value?.ToString() ?? "price_asc";
        _currentPage = 1;
        await RefreshProductsAsync();
    }

    private async Task GoToPageAsync(int page)
    {
        if (page < 1 || page > _totalPages) return;
        _currentPage = page;
        await RefreshProductsAsync();
    }

    private async Task RefreshProductsAsync()
    {
        try
        {
            _error = null;
            await SearchProductsAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private async Task RetryAsync()
    {
        await LoadDataAsync();
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            _selectedCategories.Add(category);
        else
            _selectedCategories.Remove(category);
    }

    private void OnProductSelected(Product product)
    {
        // Parent-level handling for navigation to detail page
        // In a real app, inject NavigationManager and navigate:
        // NavigationManager.NavigateTo($"/product/{product.Id}");
    }

    private void OnAddToCart(Product product)
    {
        // Handle add to cart logic
    }
}
"}

